"use client";

import "../../styles/teum-base.css";
import "../../styles/components/data-state.css";
import { MagnifyingGlass, WarningCircle } from "@phosphor-icons/react";
import type { HTMLAttributes, ReactNode } from "react";
import { cn } from "../../lib/cn";
import { Spinner } from "./spinner";

export type DataStateProps = HTMLAttributes<HTMLDivElement> & {
  state: "loading" | "empty" | "error";
  title?: ReactNode;
  description?: ReactNode;
  action?: ReactNode;
};

export function DataState({ state, title, description, action, className, ...props }: DataStateProps) {
  const defaults = state === "loading"
    ? { title: "Loading data", description: "This view will update when the data is ready." }
    : state === "error"
      ? { title: "Data could not be loaded", description: "Try again or change the active filters." }
      : { title: "No results", description: "Try changing the search or active filters." };
  return (
    <div
      className={cn("teum-data-state", className)}
      data-state={state}
      role={state === "error" ? "alert" : "status"}
      aria-live={state === "loading" ? "polite" : undefined}
      {...props}
    >
      <span className="teum-data-state__icon" aria-hidden="true">
        {state === "loading" ? <Spinner label="Loading" role="presentation" aria-hidden="true" /> : state === "error" ? <WarningCircle /> : <MagnifyingGlass />}
      </span>
      <strong>{title ?? defaults.title}</strong>
      <p>{description ?? defaults.description}</p>
      {action && <div className="teum-data-state__action">{action}</div>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-data-state {
  display: grid;
  min-width: 0;
  min-height: 176px;
  place-content: center;
  justify-items: center;
  gap: 5px;
  padding: 24px;
  border-radius: var(--teum-radius-container);
  background: color-mix(in oklch, var(--teum-bg-stage) 72%, transparent);
  text-align: center;
}

.teum-data-state__icon {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  margin-bottom: 3px;
  border-radius: 8px;
  background: var(--teum-bg-subtle);
  color: var(--teum-fg-muted);
}

.teum-data-state__icon > svg { width: 15px; height: 15px; }

.teum-data-state__icon .teum-loading-spinner { width: 14px; height: 14px; }

.teum-data-state > strong { color: var(--teum-fg-default); font-size: var(--teum-type-ui); font-weight: 590; }

.teum-data-state > p { max-width: 280px; margin: 0; color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); line-height: 1.45; }

.teum-data-state__action { margin-top: 7px; }

.teum-data-state[data-state="error"] .teum-data-state__icon { background: color-mix(in oklch, var(--teum-fg-danger) 9%, transparent); color: var(--teum-fg-danger); }
}
